# Classic OOP with bless
package Animal;

sub new {
    my ($class, %args) = @_;
    my $self = {
        name  => $args{name},
        sound => $args{sound} // "...",
    };
    return bless $self, $class;    # bless makes it an object
}

sub name  { $_[0]->{name} }
sub sound { $_[0]->{sound} }
sub speak {
    my $self = shift;
    return $self->name . " says " . $self->sound;
}

package Dog;
use parent 'Animal';    # inheritance

sub new {
    my ($class, %args) = @_;
    $args{sound} = "Woof";
    my $self = $class->SUPER::new(%args);  # call parent
    $self->{breed} = $args{breed};
    return $self;
}

sub speak { $_[0]->SUPER::speak() . "!" }

